// Normalize + enrich the call record. Caller passes:
// { provider, endpoint, method, url, request_body, workflow_name, execution_id, price_table? }
const item = items[0].json;
const rec = {
  provider: item.provider || 'unknown',
  endpoint: item.endpoint || (item.url || ''),
  method: (item.method || 'GET').toUpperCase(),
  url: item.url || '',
  request_body: item.request_body ?? null,
  workflow_name: item.workflow_name || 'unassigned',
  execution_id: item.execution_id || null,
  attempt: item.attempt || 1,
  requested_at: new Date().toISOString(),
  // per-call price table override (caller may embed provider rates)
  price_table: item.price_table || null,
  _credentials_name: item.credentials_name || null
};
return [{ json: rec }];

// Extract cost from response if provider returns it; else consult price table; else null.
// HTTP node output: { statusCode, body, headers } (neverError=true so failures flow here too)
const rec = $('Normalize Record').first().json;
const resp = items[0].json;
const ok = resp.statusCode >= 200 && resp.statusCode < 300;

// 1) provider-declared usage/cost (OpenAI/Anthropic style)
let cost_usd = null, usage = null;
const body = resp.body ?? resp;
if (body && typeof body === 'object') {
  usage = body.usage ?? body.metrics ?? null;
  if (usage) {
    // generic: usage.cost / usage.total_cost / tokens*rate
    if (typeof usage.cost === 'number') cost_usd = usage.cost;
    else if (typeof usage.total_cost === 'number') cost_usd = usage.total_cost;
  }
}

// 2) price table fallback: { provider: { endpoint_or_default: {unit_cost, unit_name} } }
let pricing_basis = null;
if (cost_usd == null && rec.price_table) {
  const t = rec.price_table[rec.provider] || {};
  const rule = t[rec.endpoint] ?? t['default'] ?? null;
  if (rule) {
    pricing_basis = rule.unit_name || 'per_call';
    cost_usd = rule.unit_cost;  // flat per-call price
  }
}

const logRow = {
  provider: rec.provider,
  endpoint: rec.endpoint,
  method: rec.method,
  workflow_name: rec.workflow_name,
  execution_id: rec.execution_id,
  attempt: rec.attempt,
  status_code: resp.statusCode ?? null,
  success: ok,
  cost_usd: cost_usd,
  pricing_basis: pricing_basis,          // 'usage.cost' | price-table rule | null(unknown)
  usage: usage,
  latency_ms: null,
  requested_at: rec.requested_at,
  logged_at: new Date().toISOString(),
  needs_reconciliation: (cost_usd == null) || !ok
};
return [{ json: logRow, pairedItem: { item: 0 } }];
